def removeInvalidParentheses(s: str) -> list[str]:
    def is_valid(sub):
        cnt = 0
        for ch in sub:
            if ch == '(': cnt += 1
            elif ch == ')':
                cnt -= 1
                if cnt < 0: return False
        return cnt == 0
    from collections import deque
    queue = deque([s])
    visited = {s}
    found = False
    res = []
    while queue:
        curr = queue.popleft()
        if is_valid(curr):
            res.append(curr)
            found = True
        if found: continue
        for i in range(len(curr)):
            if curr[i] not in '()': continue
            nxt = curr[:i] + curr[i + 1:]
            if nxt not in visited:
                visited.add(nxt)
                queue.append(nxt)
    return sorted(res)

